import{_ as d,o as e,c as o,ai as r}from"./chunks/framework.Ba-VnP44.js";const b=JSON.parse('{"title":"求职作品集 P0 审计报告（仅审计，不改站）","description":"","frontmatter":{},"headers":[],"relativePath":"plan/job-portfolio-p0-audit-2026-10-30.md","filePath":"plan/job-portfolio-p0-audit-2026-10-30.md"}'),s={name:"plan/job-portfolio-p0-audit-2026-10-30.md"};function a(n,t,c,i,h,l){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="求职作品集-p0-审计报告-仅审计-不改站" tabindex="-1">求职作品集 P0 审计报告（仅审计，不改站） <a class="header-anchor" href="#求职作品集-p0-审计报告-仅审计-不改站" aria-label="Permalink to “求职作品集 P0 审计报告（仅审计，不改站）”">​</a></h1><blockquote><p><strong>审计日期</strong>：2026-10-30<br><strong>仓库</strong>：<code>E:\\vitepress</code>（<code>main</code>，相对 <code>origin/main</code> <strong>ahead 3</strong>，推送曾因网络失败）<br><strong>目标岗位</strong>：洛阳本地或远程 · Java 全栈 / AI 应用开发 · 期望 6k+<br><strong>约束遵守</strong>：未大规模改站、未改简历事实、未猜测补业绩、未提交 Git、未推送；未覆盖用户未跟踪文件（<code>.workbuddy*</code>、<code>docs/docs/</code> 等仍保留）。</p></blockquote><p><strong>审计依据</strong>：<code>docs/index.md</code>、<code>docs/guide/my-resume.md</code>、<code>docs/about/index.md</code>、<code>docs/apps/ai/modeldesk.md</code>、<code>docs/instances/**</code>、<code>docs/apps/openbiz/**</code>、<code>docs/plan/index.md</code>、根目录 <code>TASKS.md</code>、<code>docs/.vitepress/config.mts</code>；公开链接抽检 GitHub <code>modeldesk</code> / <code>my-vitepress-site</code>（200）。</p><hr><h2 id="_0-结论摘要" tabindex="-1">0. 结论摘要 <a class="header-anchor" href="#_0-结论摘要" aria-label="Permalink to “0. 结论摘要”">​</a></h2><table tabindex="0"><thead><tr><th>层级</th><th>判断</th></tr></thead><tbody><tr><td>首页求职定位</td><td><strong>基本可用</strong>：岗位、地域、6k+、简历入口、代表项目表齐全</td></tr><tr><td>最大风险</td><td><strong>同一名称指两套东西</strong>（公司 MES/悟空 CRM vs OpenBiz 试水实例）+ <strong><code>/plan/</code> 与现状严重脱节</strong> + <strong>实例矩阵状态表过期</strong></td></tr><tr><td>最强公开证据</td><td><strong>ModelDesk</strong>（GitHub + Release + 截图 + 93 测说明）</td></tr><tr><td>公司项目</td><td>简历/首页有叙述，<strong>无独立公开详情页与可点证据</strong>（符合「不公开源码」口径，但面试转化弱）</td></tr><tr><td>建议</td><td>先做「口径对齐 + 计划页冻结/改写 + 实例状态纠错」，<strong>不要</strong>为填满矩阵再开一堆新项目</td></tr></tbody></table><hr><h2 id="_1-p0-必须立即修正-误导求职官或自相矛盾" tabindex="-1">1. P0：必须立即修正（误导求职官或自相矛盾） <a class="header-anchor" href="#_1-p0-必须立即修正-误导求职官或自相矛盾" aria-label="Permalink to “1. P0：必须立即修正（误导求职官或自相矛盾）”">​</a></h2><h3 id="p0-1-·-instances-business-状态表与项目页矛盾" tabindex="-1">P0-1 · <code>/instances/business/</code> 状态表与项目页矛盾 <a class="header-anchor" href="#p0-1-·-instances-business-状态表与项目页矛盾" aria-label="Permalink to “P0-1 · /instances/business/ 状态表与项目页矛盾”">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>现象</strong></td><td><code>docs/instances/business/index.md</code> 将 CRM / ERP / PMS 一律标 <strong>📋 规划中</strong>；但 <code>docs/instances/business/crm.md</code> 写 <strong>✅ 已验证</strong>，<code>erp.md</code> 写 <strong>✅ 已试水验证</strong>；<code>docs/apps/openbiz/crm.md</code> 等亦有 E2E 实证</td></tr><tr><td><strong>路径</strong></td><td><code>docs/instances/business/index.md</code> ↔ <code>crm.md</code> / <code>erp.md</code> / <code>pms.md</code>；对照 <code>docs/apps/openbiz/*</code></td></tr><tr><td><strong>求职价值</strong></td><td>招聘方点开「规划中」再进详情却是「已验证」，会直接质疑整站可信度</td></tr><tr><td><strong>修改建议</strong></td><td>仅改状态与一句话边界：矩阵表按各项目页真实状态更新；区分「OpenBiz 试水最小闭环」与「完整 CRM 产品」；线索/跟进等未做项继续标 📋</td></tr><tr><td><strong>风险 / 需确认</strong></td><td>不把 OpenBiz 试水写成「商业悟空 CRM 已开源」；<strong>需本人确认</strong>各 openbiz-*-app 是否允许写「公开作品集可复现」及是否挂本地路径以外的仓库链接</td></tr></tbody></table><h3 id="p0-2-·-「轻量-mes」两套叙事易被当成同一个项目" tabindex="-1">P0-2 · 「轻量 MES」两套叙事易被当成同一个项目 <a class="header-anchor" href="#p0-2-·-「轻量-mes」两套叙事易被当成同一个项目" aria-label="Permalink to “P0-2 · 「轻量 MES」两套叙事易被当成同一个项目”">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>现象</strong></td><td>首页/简历：<strong>钢瓶企业轻量 MES（2024.12–2026.04）已交付</strong>（公司项目、无源码）；<code>docs/instances/industrial/mes.md</code>：<strong>OpenBiz 轻量 MES ✅ 已验证</strong>（<code>openbiz-mes-app</code>、E2E）</td></tr><tr><td><strong>路径</strong></td><td><code>docs/index.md</code> 代表项目表；<code>docs/guide/my-resume.md</code> 项目二；<code>docs/instances/industrial/mes.md</code>；<code>docs/apps/openbiz/mes</code></td></tr><tr><td><strong>求职价值</strong></td><td>避免面试被追问「GitHub 在哪 / 为何无截图」时答非所问</td></tr><tr><td><strong>修改建议</strong></td><td>首页代表项目行显式分列：「公司交付 · 钢瓶 MES（不可公开源码）」与「作品集试水 · OpenBiz MES（可本地复现）」；链接分别指向简历段落 vs instances/openbiz 页</td></tr><tr><td><strong>风险 / 需确认</strong></td><td>是否允许在站上出现客户行业「钢瓶」字样（简历已有）；<strong>勿</strong>把 openbiz-mes 截图说成钢瓶现场系统</td></tr></tbody></table><h3 id="p0-3-·-plan-仍显示第-1-天大量「未开始」-与站点现状冲突" tabindex="-1">P0-3 · <code>/plan/</code> 仍显示第 1 天大量「未开始」，与站点现状冲突 <a class="header-anchor" href="#p0-3-·-plan-仍显示第-1-天大量「未开始」-与站点现状冲突" aria-label="Permalink to “P0-3 · /plan/ 仍显示第 1 天大量「未开始」，与站点现状冲突”">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>现象</strong></td><td><code>docs/plan/index.md</code> 文首写「第 1 天已完成」，但清单大量 checkbox 仍为 <strong>未开始</strong>（导航五项、首页求职化、简历入口等）；同时 <code>TASKS.md</code>（更新至 2026-10-23）记录 S1–S4 多项 <strong>已完成</strong>；当前 <code>config.mts</code> nav 已是「首页 / 产品实例 / 解决方案 / AI 赋能与个人提效 / 关于我」</td></tr><tr><td><strong>路径</strong></td><td><code>docs/plan/index.md</code>；根目录 <code>TASKS.md</code>；<code>docs/.vitepress/config.mts</code>（<code>nav</code>）</td></tr><tr><td><strong>求职价值</strong></td><td>计划页若被打开，像「工程管理混乱」；与「可交付工程师」人设相反</td></tr><tr><td><strong>修改建议</strong></td><td><strong>二选一（需本人定）</strong>：① 将 <code>/plan/</code> 改为「历史基线 + 指向 TASKS.md / 新进度页」并置顶「勿按未勾选项理解现状」；② 按现状批量勾选已完成项并改 nav 目标描述。<strong>不要</strong>再按旧「五栏目·功能开发」清单开工</td></tr><tr><td><strong>风险</strong></td><td>大段改计划易与真实历史冲突；优先加「现状声明」再逐步勾选</td></tr></tbody></table><h3 id="p0-4-·-公开站点可能落后于本地-3-个提交" tabindex="-1">P0-4 · 公开站点可能落后于本地 3 个提交 <a class="header-anchor" href="#p0-4-·-公开站点可能落后于本地-3-个提交" aria-label="Permalink to “P0-4 · 公开站点可能落后于本地 3 个提交”">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>现象</strong></td><td><code>git status</code>：<code>main...origin/main [ahead 3]</code>；此前 push 曾因 GitHub 网络失败</td></tr><tr><td><strong>路径</strong></td><td>仓库 Git 状态；线上 <code>https://gao-shu.github.io/my-vitepress-site/</code></td></tr><tr><td><strong>求职价值</strong></td><td>投递前若线上看不到最新口径，等于白改</td></tr><tr><td><strong>修改建议</strong></td><td>网络恢复后 <strong>只推送</strong>，不重做内容；推送后抽检首页 / ModelDesk / instances 状态</td></tr><tr><td><strong>风险</strong></td><td>无内容风险；阻塞为网络</td></tr></tbody></table><h3 id="p0-5-·-简历客户名-公司名公开范围需本人确认-事实不擅自改" tabindex="-1">P0-5 · 简历客户名 / 公司名公开范围需本人确认（事实不擅自改） <a class="header-anchor" href="#p0-5-·-简历客户名-公司名公开范围需本人确认-事实不擅自改" aria-label="Permalink to “P0-5 · 简历客户名 / 公司名公开范围需本人确认（事实不擅自改）”">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>现象</strong></td><td><code>docs/guide/my-resume.md</code> 出现：蜜雪冰城、河南航天液压、锦江之家；河南浩德微视传媒、洛阳尚科、郑州卡卡罗特等全称</td></tr><tr><td><strong>路径</strong></td><td><code>docs/guide/my-resume.md</code>；首页未列客户名</td></tr><tr><td><strong>求职价值</strong></td><td>有名客户可加分，但若未获授权会变 P0 法务/信誉风险</td></tr><tr><td><strong>修改建议</strong></td><td><strong>本人确认</strong>后保留或改为「连锁茶饮 / 液压行业客户」等脱敏；审计<strong>不替你改</strong></td></tr><tr><td><strong>风险</strong></td><td>删名会削弱简历冲击力；留名须你知情同意</td></tr></tbody></table><hr><h2 id="_2-p1-能明显提升求职竞争力" tabindex="-1">2. P1：能明显提升求职竞争力 <a class="header-anchor" href="#_2-p1-能明显提升求职竞争力" aria-label="Permalink to “2. P1：能明显提升求职竞争力”">​</a></h2><h3 id="p1-1-·-ai-漫剧项目缺少「作品集级」详情页" tabindex="-1">P1-1 · AI 漫剧项目缺少「作品集级」详情页 <a class="header-anchor" href="#p1-1-·-ai-漫剧项目缺少「作品集级」详情页" aria-label="Permalink to “P1-1 · AI 漫剧项目缺少「作品集级」详情页”">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>现象</strong></td><td>首页与简历称「已发版」；<code>about</code> 写当前在做；<strong>无</strong>对等 ModelDesk 的项目详情（架构、职责边界、可讲难点、脱敏截图）；英文面试稿另有「不夸大已上线」语气（<code>docs/guide/english-interview/*</code>），与中文简历「已发版」并读易拧巴</td></tr><tr><td><strong>路径</strong></td><td><code>docs/index.md</code>；<code>docs/guide/my-resume.md</code>；<code>docs/about/index.md</code>；<code>docs/guide/english-interview/self-introduction.md</code> 等</td></tr><tr><td><strong>建议</strong></td><td>新增 <strong>脱敏</strong> 项目页（无密钥、无内部仓库）：问题背景、你负责的模块、状态机/异步任务、诚实边界「公司项目不可开源」；中英口径统一为「客户端已发版 / 试用」等<strong>你确认后的同一说法</strong></td></tr><tr><td><strong>价值</strong></td><td>这是最近一份工作，面试必问；现在只能翻简历段落</td></tr></tbody></table><h3 id="p1-2-·-modeldesk-版本表述易被追问-非造假-但要一口清" tabindex="-1">P1-2 · ModelDesk 版本表述易被追问（非造假，但要一口清） <a class="header-anchor" href="#p1-2-·-modeldesk-版本表述易被追问-非造假-但要一口清" aria-label="Permalink to “P1-2 · ModelDesk 版本表述易被追问（非造假，但要一口清）”">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>现象</strong></td><td>页内写「安装包 v0.2.1；源码 0.2.3」；抽检根 <code>package.json</code> 为 <code>0.2.3</code>；Release 页可访问。演示视频「仍在准备中」</td></tr><tr><td><strong>路径</strong></td><td><code>docs/apps/ai/modeldesk.md</code>；<code>docs/apps/ai/index.md</code>；<code>docs/apps/index.md</code></td></tr><tr><td><strong>建议</strong></td><td>首页表格增加半句「Release 安装包 0.2.1 / 源码 0.2.3」或链到项目页第二节；有余力补 1–2 分钟无 Key 演示（配置页 + Compare UI），不必真调模型</td></tr><tr><td><strong>价值</strong></td><td>减少「到底哪个版本」的无效拉扯</td></tr></tbody></table><h3 id="p1-3-·-产品实例-vs-功能开发-openbiz-实证-信息过载" tabindex="-1">P1-3 · 产品实例 vs 功能开发 / OpenBiz 实证 信息过载 <a class="header-anchor" href="#p1-3-·-产品实例-vs-功能开发-openbiz-实证-信息过载" aria-label="Permalink to “P1-3 · 产品实例 vs 功能开发 / OpenBiz 实证 信息过载”">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>现象</strong></td><td>招聘方路径分散：<code>/instances/*</code>（矩阵）、<code>/apps/openbiz/*</code>（实证）、`/apps/business</td></tr><tr><td><strong>路径</strong></td><td><code>docs/instances/ai/index.md</code>；<code>docs/apps/openbiz/index.md</code>；<code>docs/apps/index.md</code></td></tr><tr><td><strong>建议</strong></td><td>在 <code>/instances/</code> 总览加 5 行「怎么逛」：公司经历看简历 → 可跑通看 OpenBiz/ModelDesk → 方法论看 apps 实践文；<strong>不</strong>建议再开新矩阵格子</td></tr><tr><td><strong>价值</strong></td><td>10 分钟浏览路径清晰</td></tr></tbody></table><h3 id="p1-4-·-导航已变-计划与旧文章仍写旧五栏" tabindex="-1">P1-4 · 导航已变，计划与旧文章仍写旧五栏 <a class="header-anchor" href="#p1-4-·-导航已变-计划与旧文章仍写旧五栏" aria-label="Permalink to “P1-4 · 导航已变，计划与旧文章仍写旧五栏”">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>现象</strong></td><td>当前顶部：<code>首页 · 产品实例 · 解决方案 · AI 赋能与个人提效 · 关于我</code>；<code>/plan/</code>、部分改造文仍描述「功能开发 / 技术体系 / AI 实践」五栏</td></tr><tr><td><strong>路径</strong></td><td><code>config.mts</code> <code>nav</code>；<code>docs/plan/index.md</code>；<code>docs/tech-system/frontend/site-refactor-job-portfolio.md</code>（可作历史文保留）</td></tr><tr><td><strong>建议</strong></td><td>计划页与「关于本站」各加一句现行导航说明；历史改造文标明「当时目标结构」</td></tr><tr><td><strong>价值</strong></td><td>降低「站长自己都说不清栏目」感</td></tr></tbody></table><h3 id="p1-5-·-本地未跟踪垃圾目录可能污染后续提交" tabindex="-1">P1-5 · 本地未跟踪垃圾目录可能污染后续提交 <a class="header-anchor" href="#p1-5-·-本地未跟踪垃圾目录可能污染后续提交" aria-label="Permalink to “P1-5 · 本地未跟踪垃圾目录可能污染后续提交”">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>现象</strong></td><td><code>?? docs/docs/</code>（约 1400+ 构建产物）、<code>.workbuddy-ai/</code>、<code>.workbuddy/memory/</code>、<code>.workbuddy/scripts/</code></td></tr><tr><td><strong>建议</strong></td><td>确认后加入 <code>.gitignore</code> 或删除本地产物；<strong>提交时禁止 <code>git add -A</code></strong></td></tr><tr><td><strong>价值</strong></td><td>避免仓库爆炸、避免误推私有笔记</td></tr></tbody></table><hr><h2 id="_3-p2-可暂缓" tabindex="-1">3. P2：可暂缓 <a class="header-anchor" href="#_3-p2-可暂缓" aria-label="Permalink to “3. P2：可暂缓”">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>问题</th><th>路径</th><th>建议</th></tr></thead><tbody><tr><td>P2-1</td><td>期望薪资首页写「6k+」，简历写「6k–10k」</td><td><code>docs/index.md</code> / <code>my-resume.md</code></td><td>统一区间即可，非诚信问题</td></tr><tr><td>P2-2</td><td>ModelDesk 演示视频未上</td><td><code>modeldesk.md</code></td><td>有截图可暂缓</td></tr><tr><td>P2-3</td><td>历史正文约 22 个死链（TASKS 已记）</td><td>旧文章</td><td>不影响主求职路径，批量治理即可</td></tr><tr><td>P2-4</td><td><code>open-source/mine/local-creator</code> 标试用/建议私有</td><td><code>docs/open-source/**</code></td><td>与漫剧相关则链到脱敏页，否则折叠到「其他」</td></tr><tr><td>P2-5</td><td>手机号已脱敏，邮箱全文公开</td><td><code>my-resume.md</code></td><td>可接受；若垃圾邮件多再改表单</td></tr><tr><td>P2-6</td><td>instances 部分页仍堆「规划要点」而状态已试水</td><td>如 <code>oa.md</code> 等</td><td>与 P0-1 同类，按模块分批改状态即可</td></tr><tr><td>P2-7</td><td><code>ai-suite-py</code> 等新 Python 套件尚未进作品集导航</td><td>（仓库在 <code>for-job</code>，站内未挂）</td><td><strong>暂缓</strong>：先稳住现有口径，再决定是否加「Python 多产品套件」条目</td></tr></tbody></table><hr><h2 id="_4-代表项目逐项记录" tabindex="-1">4. 代表项目逐项记录 <a class="header-anchor" href="#_4-代表项目逐项记录" aria-label="Permalink to “4. 代表项目逐项记录”">​</a></h2><h3 id="_4-1-modeldesk" tabindex="-1">4.1 ModelDesk <a class="header-anchor" href="#_4-1-modeldesk" aria-label="Permalink to “4.1 ModelDesk”">​</a></h3><table tabindex="0"><thead><tr><th>检查项</th><th>记录</th></tr></thead><tbody><tr><td>状态是否准确</td><td><strong>基本准确</strong>：已发布、可验证；安装包与源码版本差已写明</td></tr><tr><td>证据链接</td><td>GitHub / Releases <strong>抽检 200</strong>；站内截图文件存在</td></tr><tr><td>截图/视频/测试</td><td>3 张真实截图；视频未就绪；93 测 + smoke + build 有文字表</td></tr><tr><td>个人职责</td><td>清晰（作者/全栈）</td></tr><tr><td>技术难点</td><td>Compare 部分失败、网关别名等有写</td></tr><tr><td>敏感信息</td><td>未发现密钥；诚实声明未跑真实 Key</td></tr><tr><td>版本不一致</td><td><strong>0.2.1 vs 0.2.3</strong> 需口头统一（见 P1-2）</td></tr></tbody></table><h3 id="_4-2-轻量-mes" tabindex="-1">4.2 轻量 MES <a class="header-anchor" href="#_4-2-轻量-mes" aria-label="Permalink to “4.2 轻量 MES”">​</a></h3><table tabindex="0"><thead><tr><th>检查项</th><th>记录</th></tr></thead><tbody><tr><td>状态</td><td><strong>公司 MES「已交付」</strong>与 <strong>OpenBiz MES「已验证」</strong>并存（P0-2）</td></tr><tr><td>证据</td><td>公司侧：简历叙述，无公开仓；OpenBiz：<code>instances</code> + <code>apps/openbiz/mes</code> + 本地工程路径</td></tr><tr><td>截图/视频</td><td>公司现场截图未见公开页；OpenBiz 以 E2E 文字为主</td></tr><tr><td>职责</td><td>公司侧「主导/五端」较完整；OpenBiz 页偏工程实证</td></tr><tr><td>敏感</td><td>行业「钢瓶」、现场系统勿泄内部地址</td></tr><tr><td>不一致</td><td><strong>命名碰撞</strong>为最大问题</td></tr></tbody></table><h3 id="_4-3-crm-erp-oa" tabindex="-1">4.3 CRM / ERP / OA <a class="header-anchor" href="#_4-3-crm-erp-oa" aria-label="Permalink to “4.3 CRM / ERP / OA”">​</a></h3><table tabindex="0"><thead><tr><th>检查项</th><th>记录</th></tr></thead><tbody><tr><td>状态</td><td>简历：悟空套件约 4 年已交付；OpenBiz CRM/ERP/OA：<strong>试水已验证</strong> vs <strong>business 总览仍写规划中</strong>（P0-1）</td></tr><tr><td>证据</td><td>OpenBiz 有 E2E/端口说明；悟空无公开源码（符合声明）</td></tr><tr><td>截图</td><td>公开详情页缺少悟空侧脱敏图</td></tr><tr><td>职责</td><td>组长 + 多客户定制，叙述完整</td></tr><tr><td>敏感</td><td>客户名列表（P0-5）；勿把 openbiz-crm 说成蜜雪项目</td></tr><tr><td>不一致</td><td>矩阵状态过期；「商业交付」与「作品集试水」未分层</td></tr></tbody></table><h3 id="_4-4-ai-漫剧生产链路" tabindex="-1">4.4 AI 漫剧生产链路 <a class="header-anchor" href="#_4-4-ai-漫剧生产链路" aria-label="Permalink to “4.4 AI 漫剧生产链路”">​</a></h3><table tabindex="0"><thead><tr><th>检查项</th><th>记录</th></tr></thead><tbody><tr><td>状态</td><td>首页/简历「已发版」；英文材料偏谨慎（P1-1）</td></tr><tr><td>证据链接</td><td><strong>无</strong>公开 GitHub；合理但转化弱</td></tr><tr><td>截图/视频</td><td>站内未见脱敏演示页</td></tr><tr><td>职责</td><td>多模型、异步任务、三产品 0→1 等——<strong>待你确认是否仍全部属实且可对外说</strong></td></tr><tr><td>难点</td><td>简历点到状态机/重试；缺独立技术深挖页</td></tr><tr><td>敏感</td><td>公司项目，禁止贴内部仓/密钥</td></tr><tr><td>不一致</td><td>中英语气；与 <code>local-creator</code> 开源页关系未说明</td></tr></tbody></table><hr><h2 id="_5-导航与建设计划" tabindex="-1">5. 导航与建设计划 <a class="header-anchor" href="#_5-导航与建设计划" aria-label="Permalink to “5. 导航与建设计划”">​</a></h2><table tabindex="0"><thead><tr><th>观察</th><th>说明</th></tr></thead><tbody><tr><td>顶部导航</td><td>现行 5 项偏「产品实例 + 方案 + AI + 关于」；<strong>技术体系/功能开发不在顶栏</strong>（可能进侧栏矩阵）——与 <code>/plan/</code> 旧目标不一致</td></tr><tr><td>已验证 / 在建 / 规划</td><td>apps 分类页有分层意识；<strong>instances 模块总览表未跟上</strong></td></tr><tr><td><code>/plan/</code></td><td>基线过期（P0-3）；实时真相在 <code>TASKS.md</code>，但访客默认进 <code>/plan/</code></td></tr><tr><td>重复/低价值</td><td>大量学习笔记仍可达（<code>/more/</code>、旧 guide）；求职主路径应收敛到：首页 → 简历 → ModelDesk → OpenBiz 实证 → 脱敏公司项目</td></tr><tr><td>勿扩矩阵</td><td>OpenBiz 9 应用已够「可复制底座」故事；<strong>不建议</strong>再规划一堆 📋 空项目充数</td></tr></tbody></table><hr><h2 id="_6-建议执行顺序-下一轮修改用" tabindex="-1">6. 建议执行顺序（下一轮修改用） <a class="header-anchor" href="#_6-建议执行顺序-下一轮修改用" aria-label="Permalink to “6. 建议执行顺序（下一轮修改用）”">​</a></h2><ol><li><strong>P0-4</strong> 网络恢复后推送，保证线上看的是当前口径。</li><li><strong>P0-3</strong> 冻结/改写 <code>/plan/</code> 现状声明（或勾选已完成），停止按旧清单执行。</li><li><strong>P0-1</strong> 修正 <code>instances/business/index.md</code>（及同类模块总览）状态列。</li><li><strong>P0-2</strong> 首页代表项目表拆分「公司 MES」与「OpenBiz MES」。</li><li><strong>P0-5</strong> 你确认客户名/公司名公开策略后，再动简历一字。</li><li><strong>P1-1</strong> 漫剧脱敏详情页 + 中英口径统一。</li><li><strong>P1-2～P1-4</strong> 版本半句、逛站指引、导航说明。</li><li><strong>P1-5</strong> gitignore <code>docs/docs/</code> 与 workbuddy 杂项。</li><li>P2 按需。</li></ol><hr><h2 id="_7-需要本人确认的事实清单-审计不代填" tabindex="-1">7. 需要本人确认的事实清单（审计不代填） <a class="header-anchor" href="#_7-需要本人确认的事实清单-审计不代填" aria-label="Permalink to “7. 需要本人确认的事实清单（审计不代填）”">​</a></h2><ol><li>客户名（蜜雪冰城等）是否允许继续公开。</li><li>「试用期内主导 3 个主产品 0→1」「漫创客户端已发版」是否仍是对外标准表述。</li><li>OpenBiz 各 app 是否可写「公开可克隆复现」，仓库是否在 GitHub。</li><li>钢瓶 MES 是否允许继续写行业与「五端」细节。</li><li>现行顶部导航是否为你认可的求职最终结构（相对旧五栏）。</li><li><code>/plan/</code> 希望保留为历史，还是改成活进度板。</li></ol><hr><h2 id="_8-本次交付物与未做事项" tabindex="-1">8. 本次交付物与未做事项 <a class="header-anchor" href="#_8-本次交付物与未做事项" aria-label="Permalink to “8. 本次交付物与未做事项”">​</a></h2><table tabindex="0"><thead><tr><th>已交付</th><th>本文件：<code>docs/plan/job-portfolio-p0-audit-2026-10-30.md</code></th></tr></thead><tbody><tr><td><strong>未做</strong></td><td>未改首页/简历/导航；未删文；未批量改 URL；未 commit；未 push；未编造业绩</td></tr></tbody></table><hr><p><em>审计结束。下一轮请按 §6 顺序只改 P0，改完再考虑 P1。</em></p>',57)])])}const p=d(s,[["render",a]]);export{b as __pageData,p as default};
